arguments.file_text:
@page "/catalog"
@using sv_ac31c758b367474d9b215c32a2b8c115.Components.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h3 class="mb-4">Product Catalog</h3>

<div class="row">
    @* Left sidebar — filters *@
    <div class="col-md-3 mb-3">
        <CatalogFilters Categories="_categories" OnFilterApplied="HandleFilterApplied" />
    </div>

    @* Main content area *@
    <div class="col-md-9">
        @if (_error is not null)
        {
            <div class="alert alert-danger" role="alert">
                <strong>Error:</strong> @_error
                <button class="btn btn-link p-0 ms-2" @onclick="RetryLoad">Retry</button>
            </div>
        }
        else if (_loading)
        {
            <div class="d-flex justify-content-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading products…</span>
                </div>
            </div>
        }
        else
        {
            <CatalogToolbar SortBy="@_sortBy"
                            TotalCount="@_totalCount"
                            Page="@_page"
                            PageSize="@PageSize"
                            OnSortChanged="HandleSortChanged" />

            @if (_products.Count == 0)
            {
                <div class="alert alert-info text-center" role="status">
                    No products match your filters. Try adjusting or clearing them.
                </div>
            }
            else
            {
                <ProductGrid Products="_products"
                             OnProductSelected="OnProductSelected"
                             OnAddToCart="HandleAddToCart" />

                <CatalogPagination CurrentPage="_page"
                                   TotalPages="_totalPages"
                                   OnPageChanged="HandlePageChanged" />
            }
        }
    </div>
</div>

@code {
    private const int PageSize = 12;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<Product> _products = [];
    private List<string> _categories = [];
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _page = 1;
    private int _totalCount;
    private int _totalPages;
    private bool _loading = true;
    private string? _error;

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        _loading = true;
        _error = null;

        try
        {
            // Load categories and first page in parallel
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(_filter, _sortBy, _page, PageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            _categories = await categoriesTask;
            var result = await productsTask;

